# New hypothesis: Connect ALL pairs of special points sharing a row OR column
def connect_all_pairs(points):
    """Fill between all pairs of points that share row or column"""
    result = set()
    # Sort points by index within their dimension
    sorted_pts = sorted(enumerate(points))  # (index, value)

    for i in range(len(sorted_pts)):
        idx_i, val_i = sorted_pts[i]
        for j in range(i+1, len(sorted_pts)):
            idx_j, val_j = sorted_pts[j]

            # Check if they share the primary axis (column for row data, row for col data)
            if idx_i == idx_j:  # Same position (shouldn't happen here)
                continue

            # They're different positions along one axis
            start = min(idx_i, idx_j)
            end = max(idx_i, idx_j)
            for k in range(start + 1, end):
                result.add(k)

    return result

