# Fix the connect-all-pairs function
def connect_all_pairs_fixed(pts):
    """Fill between all pairs of points that share row or column"""
    result = set()

    for i in range(len(pts)):
        for j in range(i+1, len(pts)):
            pos_i = pts[i]
            pos_j = pts[j]

            # Fill all positions strictly between them
            start = min(pos_i, pos_j) + 1
            end = max(pos_i, pos_j)
            for k in range(start, end):
                result.add(k)

    return sorted(result)

